mapper.select:
SELECT /* SQL-ID: isry.couns.taskwkschmng.schprecon.mapper.workChgAplylMapper.selectWorkListTo */ (SELECT C##RG.DEC_B64(SCA100.FLNM_ENCPT) FROM SCA100 , SAA200 WHERE DD.USER_ID = SAA200.USER_ID AND SAA200.ENFSN_NO = SCA100.ENFSN_NO ) AS FLNM , DD.WORK_YMD || ', ' || MM.BGNG_HR || ' ~ ' || MM.END_HR AS WORKER_TO , DD.TASKWK_SCHDL_SN AS TASKWK_SCHDL_SN_TO , DD.USER_ID AS ID_TO , MM.BGNG_HR || ' ~ ' || MM.END_HR AS TIME_TO , DD.WORK_YMD AS WORK_YMD_TO , MM.BGNG_HR AS BGNG_HR_TO , MM.END_HR AS END_HR_TO , ROWNUM AS RN FROM AYC110 MM , AYC100 DD WHERE MM.BIZ_PLAN_MNG_NO = DD.BIZ_PLAN_MNG_NO
AND DD.WORK_YMD = #{WORKYMD} AND DD.TASKWK_TYPE_DEPT_CD = #{deptCd} AND DD.USER_ID != #{USERID}
ORDER BY MM.BGNG_HR, DD.USER_ID ASC

mapper.insert:

INSERT  INTO    AYC140
(
        INDEX_SN
    ,   CHG_DMND_ID                 /* 변경요청아이디 */
    ,   CHG_DMND_WORK_YMD           /* 변경요청근무일자 */
    ,   CHG_DMND_WORK_HR_CN         /* 변경요청근무시간내용 */
    ,   CHG_DMND_SN                 /* 변경요청일련번호 */
    ,   CHG_TRGT_ID                 /* 변경대상아이디 */
    ,   CHG_TRGT_WORK_YMD           /* 변경대상근무일자 */
    ,   CHG_TRGT_WORK_HR_CN         /* 변경대상근무시간내용 */
    ,   CHG_TRGT_SN                 /* 변경대상일련번호 */
    ,   CHG_CS_CN                   /* 변경사유내용 */
    ,   APRV_PSBLTY_YN              /* 승인가능여부 */
    ,   APRV_STTS_SE_CD             /* 승인상태구분코드 */
    ,   FRST_RGTR_ID
    ,   FRST_REG_DT
    ,   LAST_MDFR_ID
    ,   LAST_MDFCN_DT
)
VALUES
(
        AYC140_SQ01.NEXTVAL
    ,   #{CHG_DMND_ID}
    ,   #{CHG_DMND_YMD}
    ,   #{CHG_DMND_TIME}
    ,   #{CHG_DMND_SN}
    ,   #{CHG_TRGT_ID}
    ,   #{CHG_TRGT_YMD}
    ,   #{CHG_TRGT_TIME}
    ,   #{CHG_TRGT_SN}
    ,   #{CHG_CS_CN}
    ,   #{APRV_PSBLTY_YN}
    ,   '0'
    ,   #{loginId}
    ,   SYSDATE
    ,   #{loginId}
    ,   SYSDATE
)

mapper.delete:


DELETE FROM    AYC140 
WHERE  INDEX_SN          =     #{INDEX_SN}
   AND APRV_STTS_SE_CD   =     '0'
